style.css:
/* Changer la couleur de fond */
body {
    background-color: #1e1e1e; /* Fond noir/gris */
    color: #ffffff; /* Texte blanc */
}

/* Arrondir les boîtes et ajouter un effet */
div, p, span {
    border-radius: 10px; /* Coins arrondis */
    padding: 10px;
    background-color: rgba(255, 255, 255, 0.1); /* Boîte semi-transparente */
    backdrop-filter: blur(5px); /* Effet de flou */
}
